H.background();
const M = Math.max(0.01, P.M);
const grams = Math.max(0, P.grams);
const NA = 6.022e23;
const n = grams / M;
const particles = n * NA;
H.text("Mole concept: n = mass / M,  N = n * NA", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Grams convert to moles via molar mass M, then to particles via Avogadro's number.", 24, 52, { color: H.colors.sub, size: 13 });

const pulse = 0.5 + 0.5 * Math.sin(t * 1.2);
const bx = 60, bw = 560, bh = 36, gap = 70;
const rows = [
  { y: 110, label: "mass = " + grams.toFixed(1) + " g", frac: Math.min(1, grams / 100), col: H.colors.accent },
  { y: 110 + gap, label: "n = " + n.toFixed(3) + " mol", frac: Math.min(1, n / 5), col: H.colors.good },
  { y: 110 + 2 * gap, label: "N = " + particles.toExponential(2) + " particles", frac: Math.min(1, particles / (5 * NA)), col: H.colors.violet }
];
for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  H.rect(bx, r.y, bw, bh, { stroke: H.colors.grid, width: 1, radius: 6 });
  const w = Math.max(0, r.frac * bw);
  H.rect(bx, r.y, w, bh, { fill: r.col, radius: 6 });
  H.text(r.label, bx, r.y - 8, { color: H.colors.ink, size: 13, weight: 700 });
  H.circle(bx + w * (0.6 + 0.4 * pulse), r.y + bh / 2, 6, { fill: H.colors.yellow });
  if (i < rows.length - 1) H.arrow(bx + bw / 2, r.y + bh + 6, bx + bw / 2, r.y + gap - 14, { color: H.colors.sub, width: 2 });
}
H.text("/ M", bx + bw / 2 + 10, 110 + bh + 28, { color: H.colors.sub, size: 12 });
H.text("x Na", bx + bw / 2 + 10, 110 + gap + bh + 28, { color: H.colors.sub, size: 12 });
H.text("M = " + M.toFixed(1) + " g/mol", 660, 128, { color: H.colors.accent2, size: 14, weight: 700 });
H.text("n = " + n.toFixed(3) + " mol", 660, 198, { color: H.colors.good, size: 14, weight: 700 });
H.text("Na = 6.022e23 /mol", 660, 268, { color: H.colors.violet, size: 13 });
